  "tabs/basic": "&lt;<span class=\"tok-t\">Tabs</span> defaultValue=<span class=\"tok-s\">\"overview\"</span>&gt;\n  &lt;<span class=\"tok-t\">TabsList</span> label=<span class=\"tok-s\">\"资源详情分组\"</span> items={[\n    { value: <span class=\"tok-s\">'overview'</span>, label: <span class=\"tok-s\">'概览'</span> },\n    { value: <span class=\"tok-s\">'history'</span>, label: <span class=\"tok-s\">'历史'</span> },\n  ]} /&gt;\n  &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"overview\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;概览：当前资源的摘要与关键状态。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n  &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"history\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;历史：只显示合成示例内容。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n&lt;/<span class=\"tok-t\">Tabs</span>&gt;",
  "tabs/controlled": "<span class=\"tok-k\">import</span> { useState } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'react'</span>;\n\n<span class=\"tok-k\">const</span> [tab, setTab] = useState(<span class=\"tok-s\">'overview'</span>);\n\n&lt;<span class=\"tok-t\">div</span>&gt;\n  &lt;<span class=\"tok-t\">Tabs</span> value={tab} onValueChange={setTab}&gt;\n    &lt;<span class=\"tok-t\">TabsList</span> label=<span class=\"tok-s\">\"受控标签组\"</span> items={[\n      { value: <span class=\"tok-s\">'overview'</span>, label: <span class=\"tok-s\">'概览'</span> },\n      { value: <span class=\"tok-s\">'history'</span>, label: <span class=\"tok-s\">'历史'</span> },\n    ]} /&gt;\n    &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"overview\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;概览面板。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n    &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"history\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;历史面板。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n  &lt;/<span class=\"tok-t\">Tabs</span>&gt;\n  &lt;<span class=\"tok-t\">p</span>&gt;当前标签：{tab}&lt;/<span class=\"tok-t\">p</span>&gt;\n&lt;/<span class=\"tok-t\">div</span>&gt;",
  "tabs/disabled": "&lt;<span class=\"tok-t\">Tabs</span> defaultValue=<span class=\"tok-s\">\"overview\"</span>&gt;\n  &lt;<span class=\"tok-t\">TabsList</span> label=<span class=\"tok-s\">\"带禁用项的标签组\"</span> items={[\n    { value: <span class=\"tok-s\">'overview'</span>, label: <span class=\"tok-s\">'概览'</span> },\n    { value: <span class=\"tok-s\">'history'</span>, label: <span class=\"tok-s\">'历史'</span> },\n    { value: <span class=\"tok-s\">'locked'</span>, label: <span class=\"tok-s\">'不可用'</span>, disabled: true },\n  ]} /&gt;\n  &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"overview\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;禁用项不会进入方向键与 Tab 顺序。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n  &lt;<span class=\"tok-t\">TabsContent</span> value=<span class=\"tok-s\">\"history\"</span>&gt;&lt;<span class=\"tok-t\">p</span>&gt;历史面板。&lt;/<span class=\"tok-t\">p</span>&gt;&lt;/<span class=\"tok-t\">TabsContent</span>&gt;\n&lt;/<span class=\"tok-t\">Tabs</span>&gt;",
