  "toast/import": "<span class=\"tok-k\">import</span> { Toast } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'@radish-ui/react'</span>;\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">'@radish-ui/react/styles.css'</span>;",
  "toast/basic": "<span class=\"tok-k\">import</span> { useState } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'react'</span>;\n\n<span class=\"tok-k\">const</span> [open, setOpen] = useState(false);\n\n&lt;&gt;\n  &lt;<span class=\"tok-t\">div</span>&gt;&lt;<span class=\"tok-t\">Button</span> onClick={() =&gt; setOpen(true)}&gt;显示通知&lt;/<span class=\"tok-t\">Button</span>&gt;&lt;/<span class=\"tok-t\">div</span>&gt;\n  &lt;<span class=\"tok-t\">Toast</span> open={open} onOpenChange={setOpen} message=<span class=\"tok-s\">\"资源已保存\"</span> /&gt;\n&lt;/&gt;",
  "toast/label": "<span class=\"tok-k\">const</span> [open, setOpen] = useState(false);\n\n&lt;&gt;\n  &lt;<span class=\"tok-t\">div</span>&gt;&lt;<span class=\"tok-t\">Button</span> onClick={() =&gt; setOpen(true)}&gt;显示发布通知&lt;/<span class=\"tok-t\">Button</span>&gt;&lt;/<span class=\"tok-t\">div</span>&gt;\n  &lt;<span class=\"tok-t\">Toast</span> open={open} onOpenChange={setOpen} message=<span class=\"tok-s\">\"发布完成\"</span> label=<span class=\"tok-s\">\"发布通知\"</span> closeLabel=<span class=\"tok-s\">\"关闭发布通知\"</span> /&gt;\n&lt;/&gt;",
