  "icon-button/import": "<span class=\"tok-k\">import</span> { IconButton } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'@radish-ui/react'</span>;\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">'@radish-ui/react/styles.css'</span>;",
