  "icon-button/toolbar": "&lt;<span class=\"tok-t\">Card</span> tone=<span class=\"tok-s\">\"muted\"</span> padding=<span class=\"tok-s\">\"sm\"</span>&gt;\n  &lt;<span class=\"tok-t\">div</span>&gt;\n    &lt;<span class=\"tok-t\">IconButton</span> label=<span class=\"tok-s\">\"复制资源\"</span>&gt;&lt;<span class=\"tok-t\">Copy</span> size={16} /&gt;&lt;/<span class=\"tok-t\">IconButton</span>&gt;\n    &lt;<span class=\"tok-t\">IconButton</span> label=<span class=\"tok-s\">\"编辑资源\"</span> variant=<span class=\"tok-s\">\"secondary\"</span>&gt;&lt;<span class=\"tok-t\">Pencil</span> size={16} /&gt;&lt;/<span class=\"tok-t\">IconButton</span>&gt;\n    &lt;<span class=\"tok-t\">IconButton</span> label=<span class=\"tok-s\">\"删除资源\"</span> variant=<span class=\"tok-s\">\"danger\"</span>&gt;&lt;<span class=\"tok-t\">Trash2</span> size={16} /&gt;&lt;/<span class=\"tok-t\">IconButton</span>&gt;\n  &lt;/<span class=\"tok-t\">div</span>&gt;\n&lt;/<span class=\"tok-t\">Card</span>&gt;",
  "avatar/import": "<span class=\"tok-k\">import</span> { Avatar } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'@radish-ui/react'</span>;\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">'@radish-ui/react/styles.css'</span>;",
  "avatar/fallback": "&lt;<span class=\"tok-t\">div</span>&gt;\n  &lt;<span class=\"tok-t\">Avatar</span> name=<span class=\"tok-s\">\"林杏\"</span> /&gt;\n  &lt;<span class=\"tok-t\">Avatar</span> name=<span class=\"tok-s\">\"Ada Lovelace\"</span> /&gt;\n&lt;/<span class=\"tok-t\">div</span>&gt;",
