  "tag/import": "<span class=\"tok-k\">import</span> { Tag } <span class=\"tok-k\">from</span> <span class=\"tok-s\">'@radish-ui/react'</span>;\n<span class=\"tok-k\">import</span> <span class=\"tok-s\">'@radish-ui/react/styles.css'</span>;",
  "tag/basic": "&lt;<span class=\"tok-t\">div</span>&gt;\n  &lt;<span class=\"tok-t\">Tag</span>&gt;组件&lt;/<span class=\"tok-t\">Tag</span>&gt;\n  &lt;<span class=\"tok-t\">Tag</span>&gt;令牌&lt;/<span class=\"tok-t\">Tag</span>&gt;\n  &lt;<span class=\"tok-t\">Tag</span>&gt;可访问性&lt;/<span class=\"tok-t\">Tag</span>&gt;\n&lt;/<span class=\"tok-t\">div</span>&gt;",
